const f1 = Math.max(1, P.f1);                 // tone 1 frequency (Hz)
const f2 = Math.max(1, P.f2);                 // tone 2 frequency (Hz)
const fbeat = Math.abs(f1 - f2);              // beat frequency |f1 - f2|
const fbar = (f1 + f2) / 2;                   // carrier (heard pitch)
const TAU = Math.PI * 2;
// scroll the 1 s viewing window forward, wrapping so it loops in frame
const off = (t * 0.15) % 1;
const sig = (tt) => Math.cos(TAU * f1 * tt) + Math.cos(TAU * f2 * tt);
const envFn = (tt) => 2 * Math.abs(Math.cos(TAU * (fbeat / 2) * tt));
v.fn(x => sig(x + off), { color: H.colors.accent, width: 2 });
// slow beat envelope: 2*cos(pi*fbeat*t) - the loudness pulsing
v.fn(x => envFn(x + off), { color: H.colors.warn, width: 1.6, dash: [5, 5] });
v.fn(x => -envFn(x + off), { color: H.colors.warn, width: 1.6, dash: [5, 5] });
// a marker riding the combined wave
const xm = 0.5;
v.dot(xm, sig(xm + off), { r: 6, fill: H.colors.good });
H.text("Beats: y = cos(2pi f1 t) + cos(2pi f2 t)", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
